const fs = await import('node:fs/promises');
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const P3 = P2 + "\\_scripts";

// 1. 已有大学生底册
const doc = await fs.readFile(P2+"\\大学生人群商机-深挖.md","utf8").catch(()=>"");
// 2. 可用脚本
const scripts = (await fs.readdir(P3)).filter(f=>/\.mjs$/.test(f));
const key = scripts.filter(f=>/sogou|chrome|scrape|probe|search|arctic|reddit/i.test(f));
// 3. 关键文件存在性
const exists = async f => { try { await fs.stat(P3+"\\"+f); return true; } catch { return false; } };
const chrome = await exists("chrome-fetch.mjs");
const sogou = await exists("sogou.mjs");

return {
  docChars: doc.length,
  docHead: doc.slice(0, 1500),
  scriptCount: scripts.length,
  keyScripts: key,
  hasChromeFetch: chrome,
  hasSogou: sogou
};
